from __future__ import annotations
from typing import TypeVar, Optional
T = TypeVar('T')


class SinglyLinkedList(object):
    class Node(object):
        def __init__(self, datum: T, next_node: Optional[SinglyLinkedList.Node] = None) -> None:
            self.datum = datum
            self.next = next_node

    def __init__(self) -> None:
        self.head = None

    def __len__(self) -> int:
        n = 0
        current = self.head
        while current is not None:
            n += 1
            current = current.next
        return n

    def append(self, datum: T) -> None:
        new_node = SinglyLinkedList.Node(datum, None)
        if self.head is None:
            self.head = new_node
        else:
            current = self.head
            while current.next is not None:
                current = current.next
            current.next = new_node

    def delete(self, idx: int) -> T:
        assert idx >= 0
        if idx == 0:
            datum = self.head.datum
            self.head = self.head.next
        else:
            n = 0
            current = self.head
            while current.next is not None:
                if n == idx - 1:
                    datum = current.next.datum
                    current.next = current.next.next
                    break
                n += 1
                current = current.next
        return datum

    def __getitem__(self, idx: int) -> T:
        assert idx >= 0
        n = 0
        current = self.head
        while current is not None:
            if n == idx:
                return current.datum
            n += 1
            current = current.next
        raise IndexError("List index out of range")


